from lc import L, w, gr, q

B2 = [
 L("Living With Earthquakes in Taiwan", "在台灣與地震共處", [
   "The Earth's outer layer is broken into huge pieces called tectonic plates, which move slowly against each other. Taiwan sits where two of these plates meet, so it experiences frequent earthquakes, most of them too small to feel.",
   "Occasionally a strong one strikes. The 921 earthquake in 1999 caused enormous damage and killed around 2,400 people. Since then, Taiwan has strengthened its building rules, and many experts say this helped limit the damage when a powerful earthquake hit Hualien in 2024.",
   "Today, mobile phones can receive alerts a few seconds before strong shaking arrives. If you feel a big quake, remember three steps: drop to the ground, take cover under a sturdy table and hold on until the shaking stops."],
  [w("tectonic","adjective","/tekˈtɑː.nɪk/","地殼構造的","relating to the structure of the Earth's surface","tectonic plates","tectonic plates 板塊。"),
   w("frequent","adjective","/ˈfriː.kwənt/","頻繁的","happening often","frequent visits","frequent earthquakes 頻繁的地震。"),
   w("occasionally","adverb","/əˈkeɪ.ʒən.əl.i/","偶爾","sometimes but not often","We occasionally eat out.","放句首表示「偶爾」。"),
   w("enormous","adjective","/ɪˈnɔːr.məs/","巨大的","extremely large","an enormous house","enormous damage 巨大損害。"),
   w("alert","noun","/əˈlɝːt/","警報","a warning about danger","a weather alert","receive alerts 收到警報。"),
   w("shaking","noun","/ˈʃeɪ.kɪŋ/","搖晃","quick movement up and down or side to side","The shaking lasted a minute.","strong shaking 強烈搖晃。"),
   w("sturdy","adjective","/ˈstɝː.di/","堅固的","strong and not easily broken","a sturdy table","a sturdy table 堅固的桌子。")],
  [gr("關係副詞 where","where two of these plates meet = 兩個板塊交會處。","Taiwan sits where two of these plates meet"),
   gr("too… to…","太…以致於不能…。","most of them too small to feel"),
   gr("until + 子句","直到…為止。","hold on until the shaking stops")],
  [q("Why does Taiwan have frequent earthquakes?","It sits where two plates meet","It has many volcanoes","It is near the North Pole"),
   q("What helped limit damage in the 2024 Hualien quake, according to experts?","Stronger building rules","Better weather","Fewer people"),
   q("What should you do during a big quake?","Drop, take cover and hold on","Run outside immediately","Take the elevator")]),
 L("Libraries Are More Than Books", "圖書館不只有書", [
   "Some people think libraries are old-fashioned now that so much information is online. In fact, many libraries are busier than ever, because they have changed to meet new needs.",
   "Besides lending books, modern libraries offer free internet access, e-books, study spaces and classes on everything from coding to cooking. Some even have \"makerspaces\" with 3D printers and tools that people can borrow.",
   "Perhaps most importantly, a library is one of the few indoor public places where you can stay for hours without spending money. For students who need a quiet place to study, older people looking for company and families with young children, that makes the library a valuable part of the community."],
  [w("old-fashioned","adjective","/ˌoʊldˈfæʃ.ənd/","過時的","not modern","old-fashioned clothes","複合形容詞。"),
   w("now that","conjunction","/ˈnaʊ ðæt/","既然、由於現在","because of the new situation that","Now that I'm older, I understand.","now that + 子句。"),
   w("lend","verb","/lend/","借出","to let someone use something for a time","Can you lend me a pen?","lend 借出；borrow 借入。"),
   w("access","noun","/ˈæk.ses/","使用的機會","the chance to use something","internet access","free internet access 免費上網。"),
   w("borrow","verb","/ˈbɑːr.oʊ/","借入","to take something and give it back later","borrow a book","tools that people can borrow 可以借用的工具。"),
   w("company","noun","/ˈkʌm.pə.ni/","陪伴","being with other people","I enjoy her company.","looking for company 尋找陪伴（不可數）。"),
   w("valuable","adjective","/ˈvæl.jə.bəl/","寶貴的","very useful or important","valuable advice","a valuable part 寶貴的一部分。")],
  [gr("now that","既然（現在情況改變）。","libraries are old-fashioned now that so much information is online"),
   gr("Besides + V-ing","除了…之外（還有）。","Besides lending books, modern libraries offer free internet access"),
   gr("one of the few + 複數名詞","少數…之一。","a library is one of the few indoor public places where you can stay for hours without spending money")],
  [q("Why are many libraries busier than ever?","They have changed to meet new needs","They sell more books","They are open only at night"),
   q("What can you find in a 'makerspace'?","3D printers and tools","Only novels","A restaurant"),
   q("What makes libraries special as public places?","You can stay without spending money","They are very noisy","They are only for students")]),
 L("The Hidden Costs of One-Click Shopping", "一鍵購物的隱藏成本", [
   "Online shopping has changed the way we buy almost everything. Amazon started in the 1990s as an online bookstore, and today people around the world order clothes, food and electronics from their phones within seconds.",
   "The advantages are clear: you can compare prices easily, read reviews and avoid crowded shops. In Taiwan, many shoppers also pick up their parcels at convenience stores, which makes delivery even more convenient.",
   "However, one-click shopping has hidden costs. Fast delivery creates large amounts of packaging waste and more traffic from delivery vans. Because returning items is often free, many products are sent back, and some are simply thrown away. Easy shopping can also tempt people into buying things they do not really need."],
  [w("electronics","noun","/iˌlekˈtrɑː.nɪks/","電子產品","electronic devices such as phones and computers","consumer electronics","複數形名詞。"),
   w("compare","verb","/kəmˈper/","比較","to look at how things are similar or different","compare prices","compare prices 比價。"),
   w("review","noun","/rɪˈvjuː/","評論","an opinion about a product or film","good reviews","read reviews 看評價。"),
   w("parcel","noun","/ˈpɑːr.səl/","包裹","a package sent by post","send a parcel","pick up parcels 取包裹。"),
   w("convenient","adjective","/kənˈviː.ni.ənt/","方便的","easy to use or suitable","a convenient time","even more convenient 更方便。"),
   w("packaging","noun","/ˈpæk.ɪ.dʒɪŋ/","包裝材料","the materials used to wrap products","plastic packaging","packaging waste 包裝垃圾。"),
   w("tempt","verb","/tempt/","誘惑","to make someone want to do something","The cake tempted me.","tempt someone into + V-ing。")],
  [gr("within + 時間","在…之內。","order clothes, food and electronics from their phones within seconds"),
   gr("which 指前句","which 指在超商取貨這件事。","which makes delivery even more convenient"),
   gr("tempt sb into + V-ing","誘使某人去…。","Easy shopping can also tempt people into buying things they do not really need.")],
  [q("How did Amazon start?","As an online bookstore","As a delivery company","As a phone maker"),
   q("What do many shoppers in Taiwan do?","Pick up parcels at convenience stores","Never shop online","Pay only in cash at home"),
   q("Which hidden cost is mentioned?","Packaging waste","Cheaper prices","Fewer reviews")]),
 L("The Power of Vulnerability", "脆弱的力量", [
   "Brené Brown is a researcher who studies connection and shame. In her TED talk, she describes how years of interviews led her to an unexpected discovery about what makes people feel truly connected to others.",
   "She found that people with a strong sense of love and belonging had one thing in common: they believed they were worthy of it. These \"wholehearted\" people had the courage to be imperfect, were kind to themselves and accepted vulnerability as necessary, not as a weakness.",
   "Brown admits that this finding was hard for her personally, because she preferred to control everything. Her message is that we cannot numb painful feelings without also numbing joy. To live fully, she suggests, we need to let ourselves be seen, even when there are no guarantees."],
  [w("connection","noun","/kəˈnek.ʃən/","連結","a relationship between people","a strong connection","connection and shame 連結與羞愧。"),
   w("shame","noun","/ʃeɪm/","羞恥","a bad feeling about yourself after doing something wrong","a sense of shame","不可數名詞。"),
   w("belonging","noun","/bɪˈlɑːŋ.ɪŋ/","歸屬感","the feeling of being accepted in a group","a sense of belonging","a sense of belonging 歸屬感。"),
   w("worthy","adjective","/ˈwɝː.ði/","值得的","deserving something","worthy of respect","be worthy of + 名詞。"),
   w("imperfect","adjective","/ɪmˈpɝː.fekt/","不完美的","having faults","an imperfect world","the courage to be imperfect 不完美的勇氣。"),
   w("vulnerability","noun","/ˌvʌl.nɚ.əˈbɪl.ə.t̬i/","脆弱","being open to emotional hurt","show vulnerability","形容詞 vulnerable。"),
   w("numb","verb","/nʌm/","使麻木","to make someone unable to feel something","numb the pain","numbing joy 麻木喜悅。")],
  [gr("led sb to + 名詞","引導某人得到…。","years of interviews led her to an unexpected discovery"),
   gr("have… in common","有…共同點。","had one thing in common"),
   gr("without also + V-ing","不可能…而不同時…。","we cannot numb painful feelings without also numbing joy")],
  [q("What do Brené Brown's studies focus on?","Connection and shame","Earthquakes","Business strategy"),
   q("What did 'wholehearted' people believe?","That they were worthy of love and belonging","That they were perfect","That vulnerability is weakness"),
   q("What happens when we numb painful feelings, according to Brown?","We also numb joy","We become happier","Nothing changes")]),
]

C1 = [
 L("Building a Society That Can Withstand Earthquakes", "打造能承受地震的社會", [
   "Taiwan straddles the boundary between the Philippine Sea Plate and the Eurasian Plate, a collision zone that is still building the island's mountains. The price of that dramatic geology is seismic activity: the island records thousands of tremors a year, the vast majority too faint to notice.",
   "Its defining modern disaster came in September 1999, when the magnitude 7.3 Chi-Chi earthquake, known locally as 921, killed roughly 2,400 people and exposed serious weaknesses in construction standards.",
   "The reforms that followed tightened building codes, strengthened enforcement and retrofitted many schools. When a powerful quake struck off Hualien in April 2024, engineers widely credited those changes with keeping the toll far lower than it might otherwise have been.",
   "Technology now buys precious seconds as well. Seismic networks detect the faster but weaker initial waves and dispatch alerts to mobile phones before the more destructive shaking arrives. Those seconds are only valuable if people respond instinctively, however, which is why regular drills that rehearse 'drop, cover, hold on' remain indispensable."],
  [w("straddle","verb","/ˈstræd.əl/","橫跨","to be on both sides of something","The town straddles the border.","straddle the boundary 跨越邊界。"),
   w("seismic","adjective","/ˈsaɪz.mɪk/","地震的","relating to earthquakes","seismic waves","seismic activity 地震活動。"),
   w("tremor","noun","/ˈtrem.ɚ/","微震","a small earthquake","We felt a slight tremor.","thousands of tremors 數千次微震。"),
   w("enforcement","noun","/ɪnˈfɔːrs.mənt/","執行","making sure laws are obeyed","law enforcement","strengthened enforcement 加強執行。"),
   w("retrofit","verb","/ˈret.roʊ.fɪt/","翻修補強","to add new parts to an old building or machine","retrofit old bridges","retrofitted 過去式。"),
   w("toll","noun","/toʊl/","死傷人數、損失","the number of people killed or hurt","the death toll","keep the toll low 減少傷亡。"),
   w("dispatch","verb","/dɪˈspætʃ/","發送","to send something quickly","dispatch a message","dispatch alerts 發出警報。"),
   w("instinctively","adverb","/ɪnˈstɪŋk.tɪv.li/","本能地","without thinking","She instinctively ducked.","respond instinctively 本能反應。")],
  [gr("同位語說明","a collision zone that… 補充說明前面的板塊邊界。","a collision zone that is still building the island's mountains"),
   gr("credit A with B","把 B 歸功於 A。","engineers widely credited those changes with keeping the toll far lower"),
   gr("only if","只有在…時才。","Those seconds are only valuable if people respond instinctively")],
  [q("What did the 1999 Chi-Chi earthquake expose?","Weak construction standards","A new volcano","Faulty phone alerts"),
   q("What do engineers credit for the lower toll in 2024?","Reforms after 1999","Luck alone","The time of day"),
   q("Why are drills still needed, according to the writer?","Alerts only help if people react instinctively","Phones do not work","Buildings are perfect now")]),
 L("Why Libraries Still Matter in a Digital Age", "數位時代圖書館為何仍重要", [
   "When almost any fact can be summoned on a phone in seconds, the public library might seem destined for obsolescence. Instead, many libraries are thriving, having reinvented themselves around what the internet cannot easily supply.",
   "Their collections now extend well beyond print. Patrons borrow e-books and audiobooks, use free computers and Wi-Fi, attend workshops on everything from coding to tax returns, and experiment in makerspaces equipped with 3D printers and tools.",
   "For people without reliable home internet, these services are not a convenience but a lifeline for job applications, schoolwork and government forms.",
   "Yet the library's most distinctive role may be social rather than informational. It is one of the last indoor public spaces where anyone may linger without being expected to buy anything. Sociologists sometimes call such places 'social infrastructure', and their value becomes conspicuous when they disappear: isolated older people, students seeking quiet and parents with small children all lose a shared, neutral ground."],
  [w("summon","verb","/ˈsʌm.ən/","召喚、調出","to call or bring something up","summon help","be summoned 被叫出來。"),
   w("obsolescence","noun","/ˌɑːb.səˈles.əns/","過時、淘汰","the state of becoming out of date","planned obsolescence","destined for obsolescence 註定被淘汰。"),
   w("thrive","verb","/θraɪv/","蓬勃發展","to grow or develop successfully","Plants thrive in sun.","are thriving 正蓬勃發展。"),
   w("patron","noun","/ˈpeɪ.trən/","使用者、常客","a person who uses a library or shop","library patrons","Patrons borrow… 讀者借閱…。"),
   w("lifeline","noun","/ˈlaɪf.laɪn/","生命線","something very important that helps you survive","The bus is a lifeline for villagers.","not a convenience but a lifeline 不是便利而是命脈。"),
   w("distinctive","adjective","/dɪˈstɪŋk.tɪv/","獨特的","special and easy to recognize","a distinctive voice","most distinctive role 最獨特的角色。"),
   w("infrastructure","noun","/ˈɪn.frəˌstrʌk.tʃɚ/","基礎設施","the basic systems a society needs","transport infrastructure","social infrastructure 社會基礎設施。"),
   w("conspicuous","adjective","/kənˈspɪk.ju.əs/","顯而易見的","very noticeable","a conspicuous mistake","becomes conspicuous 變得明顯。")],
  [gr("完成式分詞構句 having + p.p.","表示原因，且動作先發生。","having reinvented themselves around what the internet cannot easily supply"),
   gr("not A but B","不是 A 而是 B。","these services are not a convenience but a lifeline"),
   gr("without being expected to","不會被期待去…（被動）。","where anyone may linger without being expected to buy anything")],
  [q("Why might libraries seem destined to disappear?","Information is easily available on phones","Books are too expensive","People stopped reading"),
   q("For whom are library services described as a 'lifeline'?","People without reliable home internet","Wealthy tech experts","Bookstore owners"),
   q("What is the library's most distinctive role, according to the writer?","A social space open to everyone","A place to buy books","A computer shop")]),
 L("The True Price of Convenience", "便利的真正代價", [
   "In barely three decades, e-commerce has evolved from a curiosity into an infrastructure we take for granted. Amazon began in the mid-1990s by selling books online; today, a few taps can summon almost anything to the doorstep within days, sometimes within hours.",
   "The benefits for consumers are genuine. Price comparison is effortless, reviews reduce the risk of a bad purchase and people with limited mobility gain access to goods they might struggle to reach. In Taiwan, collecting parcels at ubiquitous convenience stores has made the system remarkably efficient.",
   "The costs, however, are largely externalized. Rapid delivery fragments shipments into countless small packages, multiplying cardboard and plastic waste and adding delivery vans to congested streets.",
   "Generous free-return policies encourage shoppers to order several sizes and send most back, and a share of those returns is cheaper to discard than to restock. Meanwhile, interfaces engineered to minimize friction make impulse purchases almost effortless. Recognizing these trade-offs does not require abandoning online shopping, but it may justify choosing slower delivery and buying with more deliberation."],
  [w("curiosity","noun","/ˌkjʊr.iˈɑː.sə.t̬i/","新奇的事物","something unusual and interesting","a museum curiosity","from a curiosity into… 從新奇玩意變成…。"),
   w("mobility","noun","/moʊˈbɪl.ə.t̬i/","行動能力","the ability to move around","limited mobility","limited mobility 行動不便。"),
   w("ubiquitous","adjective","/juːˈbɪk.wə.t̬əs/","無所不在的","seeming to be everywhere","ubiquitous smartphones","ubiquitous convenience stores 到處都有的超商。"),
   w("externalize","verb","/ɪkˈstɝː.nə.laɪz/","外部化（把成本轉嫁他人）","to make others pay a cost","externalized costs","are externalized 被轉嫁出去。"),
   w("fragment","verb","/fræɡˈment/","使分散成碎片","to break into small parts","The party fragmented.","fragments shipments 把貨物拆得零碎。"),
   w("discard","verb","/dɪˈskɑːrd/","丟棄","to throw something away","discard old clothes","cheaper to discard than to restock 丟掉比重新上架便宜。"),
   w("friction","noun","/ˈfrɪk.ʃən/","阻力、麻煩","something that makes a process slower or harder","reduce friction","minimize friction 減少阻力。"),
   w("deliberation","noun","/dɪˌlɪb.əˈreɪ.ʃən/","深思熟慮","careful thought","after much deliberation","with more deliberation 更審慎地。")],
  [gr("evolve from A into B","從 A 演變成 B。","e-commerce has evolved from a curiosity into an infrastructure we take for granted"),
   gr("比較 cheaper to A than to B","做 A 比做 B 便宜。","a share of those returns is cheaper to discard than to restock"),
   gr("does not require… but may justify…","不需要…但也許有理由…。","Recognizing these trade-offs does not require abandoning online shopping, but it may justify choosing slower delivery")],
  [q("What does 'the costs are largely externalized' mean?","Others, such as the environment, bear the costs","Shoppers pay all the costs","Costs are hidden in reviews"),
   q("Why are some returned items thrown away?","Discarding them is cheaper than restocking","They are always broken","Shops have no space"),
   q("What does the writer recommend?","Choosing slower delivery and buying more carefully","Stopping online shopping completely","Ordering several sizes")]),
 L("Daring to Be Seen", "勇於被看見", [
   "Brené Brown introduces herself as a researcher who prefers what can be measured, which makes the subject of her famous TED talk all the more striking. After years of collecting stories about connection, she kept encountering shame, the fear that something about us makes us unworthy of connection.",
   "Sorting her data, she identified a group she calls the 'wholehearted': people with a strong sense of love and belonging. What set them apart was not luck or status but the conviction that they were worthy of it. They had the courage to be imperfect, extended compassion to themselves as well as others, and fully embraced vulnerability as integral to connection.",
   "Brown is disarmingly frank that this conclusion unsettled her. Her instinct was to control and predict, and she describes the year of reflection, with the help of a therapist, that followed.",
   "Her central insight is that emotions cannot be selectively numbed: dulling grief, fear and disappointment also mutes joy and gratitude. The alternative she proposes is to let ourselves be deeply seen, to practice gratitude and to believe that we are enough."],
  [w("striking","adjective","/ˈstraɪ.kɪŋ/","引人注目的","very noticeable or unusual","a striking contrast","all the more striking 更加引人注目。"),
   w("encounter","verb","/ɪnˈkaʊn.t̬ɚ/","遇到","to meet or experience something unexpectedly","encounter problems","kept encountering 一再遇到。"),
   w("unworthy","adjective","/ʌnˈwɝː.ði/","不值得的","not deserving something","unworthy of trust","be unworthy of… 不配…。"),
   w("set them apart","phrasal verb (set… apart)","/set əˈpɑːrt/","使與眾不同","to make different from others","Her talent sets her apart.","What set them apart 讓他們與眾不同的是。"),
   w("integral","adjective","/ˈɪn.t̬ə.ɡrəl/","不可或缺的","necessary and important as a part of a whole","an integral part","integral to… 對…不可或缺。"),
   w("disarmingly","adverb","/dɪˈsɑːr.mɪŋ.li/","令人卸下心防地","in a way that makes people feel friendly","disarmingly honest","disarmingly frank 坦率得讓人放下戒心。"),
   w("unsettle","verb","/ʌnˈset̬.əl/","使不安","to make someone feel anxious","The news unsettled her.","unsettled 過去式。"),
   w("selectively","adverb","/səˈlek.tɪv.li/","有選擇地","choosing only some things","selectively edited","cannot be selectively numbed 無法只麻木某些情緒。")],
  [gr("all the more + 形容詞","更加…（因前述原因）。","which makes the subject of her famous TED talk all the more striking"),
   gr("not A but B","讓他們不同的不是 A 而是 B。","What set them apart was not luck or status but the conviction that they were worthy of it."),
   gr("動名詞當主詞 dulling…","dulling grief… 當主詞。","dulling grief, fear and disappointment also mutes joy and gratitude")],
  [q("Why is Brown's topic surprising given her background?","She prefers things that can be measured","She is a poet","She never interviewed anyone"),
   q("What set the 'wholehearted' apart?","Believing they were worthy of love and belonging","Wealth and status","Good luck"),
   q("What is her central insight about emotions?","We cannot numb bad feelings without numbing good ones","We should avoid all feelings","Joy is more important than grief")]),
]
